import {createRouter, createWebHistory} from 'vue-router'

// ── Маршрут по роли (используется в guestOnly редиректе) ──
const ROLE_HOME = {
    super: '/',
    stadnik: '/stadnik',
    dudina: '/dudina',
    ambrosov: '/ambrosov',
    artutjan: '/artutjan',
    mjaskovskiy: '/mjaskovskiy',
    promo: '/',
}

const routes = [
    {
        path: '/',
        name: 'main',
        component: () => import('./pages/MainDataComponent.vue'),
        meta: {requiresAuth: true},
    },
    {
        path: '/login',
        name: 'login',
        component: () => import('./pages/LoginComponent.vue'),
        meta: {guestOnly: true},
    },
    {
        path: '/stadnik',
        name: 'stadnik',
        component: () => import('./pages/Stadnik.vue'),
        meta: {requiresAuth: true, roles: ['super', 'stadnik']},
    },
    {
        path: '/dudina',
        name: 'dudina',
        component: () => import('./pages/Dudina.vue'),
        meta: {requiresAuth: true, roles: ['super', 'dudina']},
    },
    {
        path: '/ambrosov',
        name: 'ambrosov',
        component: () => import('./pages/Ambrosov.vue'),
        meta: {requiresAuth: true, roles: ['super', 'ambrosov']},
    },
    {
        path: '/artutjan',
        name: 'artutjan',
        component: () => import('./pages/Artutjan.vue'),
        meta: {requiresAuth: true, roles: ['super', 'artutjan']},
    },
    {
        path: '/mjaskovskiy',
        name: 'mjaskovskiy',
        component: () => import('./pages/Mjaskovskiy.vue'),
        meta: {requiresAuth: true, roles: ['super', 'mjaskovskiy']},
    },
    {
        // 404 — требует авторизации, незалогиненный → /login
        path: '/:pathMatch(.*)*',
        name: 'error',
        component: () => import('./pages/ErrorComponent.vue'),
        meta: {requiresAuth: true},
    },
]

const router = createRouter({
    history: createWebHistory(),
    routes,
})

// ── Guard ─────────────────────────────────────────────────
router.beforeEach((to, from, next) => {
    // Безопасно читаем auth из localStorage
    let authData = null
    try {
        const raw = localStorage.getItem('sale-auth')
        authData = raw ? JSON.parse(raw) : null
    } catch {
        localStorage.removeItem('sale-auth')
    }

    // Роль вычисляем лениво — только если authData есть
    const role = authData?.role
        ? String(authData.role).trim().toLowerCase()
        : null

    // Страница требует авторизации — не залогинен → /login
    if (to.meta.requiresAuth && !authData) {
        next('/login')
        return
    }

    // Страница ограничена по ролям — роль не подходит → на свой home
    if (to.meta.roles && !to.meta.roles.includes(role)) {
        next(ROLE_HOME[role] || '/')
        return
    }

    // Страница только для гостей — уже залогинен → на свой home
    if (to.meta.guestOnly && authData) {
        next(ROLE_HOME[role] || '/')
        return
    }

    next()
})

export default router